:root {
  color-scheme: dark;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  background: #17251f;
  color: #f4f0df;
}

* { box-sizing: border-box; }

body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  display: grid;
  place-items: center;
  padding: 24px 16px;
  background: radial-gradient(ellipse at 50% 0%, #30483b 0, #17251f 65%);
}

.clock-card {
  width: min(100%, 620px);
  padding: clamp(24px, 6vw, 48px);
  border: 1px solid #52685a;
  border-radius: 24px;
  background: #22342b;
  box-shadow: 0 24px 70px #0b130f99;
  text-align: center;
}

.card-header { margin-bottom: 32px; }
.eyebrow { margin: 0 0 8px; color: #c8a96b; font-size: 0.875rem; font-weight: 800; letter-spacing: 0.16em; }
h1 { margin: 0; font-size: clamp(1.75rem, 7vw, 2.5rem); line-height: 1.15; }
.subtitle { margin: 12px 0 0; color: #c2cec4; }

.clocks { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.player-clock {
  min-width: 0;
  min-height: 210px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 20px 12px;
  border: 2px solid #52685a;
  border-radius: 16px;
  background: #17251f;
  color: #f4f0df;
  cursor: pointer;
  transition: transform 120ms ease, border-color 120ms ease, background 120ms ease;
}
.player-clock:hover { border-color: #c8a96b; background: #293c31; }
.player-clock:active { transform: scale(0.98); }
.player-clock:focus-visible, .pause-button:focus-visible { outline: 3px solid #f2d18b; outline-offset: 4px; }
.player-clock.active { border-color: #c8a96b; box-shadow: inset 0 0 0 1px #c8a96b; }
.player-clock.flagged { border-color: #ed8d73; background: #412e2b; }
.player-name { display: flex; align-items: center; gap: 8px; font-size: 1.125rem; font-weight: 700; }
.piece { font-size: 1.5rem; line-height: 1; }
.white-piece { color: #f4f0df; }
.black-piece { color: #c8a96b; }
.time { font-variant-numeric: tabular-nums; font-size: clamp(2.25rem, 10vw, 3.75rem); font-weight: 800; line-height: 1; letter-spacing: 0.02em; }
.clock-status { min-height: 1.25em; color: #c2cec4; font-size: 0.95rem; }
.flagged .clock-status { color: #ffb09a; font-weight: 800; }
.game-message { min-height: 1.5em; margin: 24px 0 16px; color: #e5d5ae; font-weight: 650; }
.pause-button {
  min-width: 150px;
  min-height: 48px;
  padding: 10px 24px;
  border: 0;
  border-radius: 10px;
  background: #c8a96b;
  color: #17251f;
  font: inherit;
  font-weight: 800;
  cursor: pointer;
  transition: transform 120ms ease, background 120ms ease;
}
.pause-button:hover:not(:disabled) { background: #dfc181; }
.pause-button:active:not(:disabled) { transform: translateY(2px); }
.pause-button:disabled { opacity: 0.55; cursor: not-allowed; }
.hint { margin: 20px 0 0; color: #aab9ad; font-size: 0.875rem; }

@media (max-width: 430px) {
  .clocks { gap: 10px; }
  .player-clock { min-height: 180px; padding-inline: 6px; }
  .player-name { font-size: 1rem; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0.01ms !important; }
}

(() => {
  const START_TIME = 5 * 60 * 1000;
  const players = {
    white: { button: document.getElementById('white-clock'), time: document.getElementById('white-time'), status: document.getElementById('white-status'), remaining: START_TIME },
    black: { button: document.getElementById('black-clock'), time: document.getElementById('black-time'), status: document.getElementById('black-status'), remaining: START_TIME }
  };
  const pauseButton = document.getElementById('pause-button');
  const message = document.getElementById('game-message');
  let activePlayer = null;
  let running = false;
  let flaggedPlayer = null;
  let lastTick = 0;
  let timerId = null;

  function formatTime(milliseconds) {
    const seconds = Math.ceil(milliseconds / 1000);
    return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`;
  }

  function render() {
    for (const [name, player] of Object.entries(players)) {
      player.time.textContent = formatTime(player.remaining);
      const isActive = running && activePlayer === name;
      player.button.classList.toggle('active', isActive);
      player.button.classList.toggle('flagged', flaggedPlayer === name);
      player.button.setAttribute('aria-pressed', String(isActive));
      player.button.setAttribute('aria-label', `${name === 'white' ? 'White' : 'Black'} clock, ${formatTime(player.remaining)} remaining. ${flaggedPlayer === name ? 'Flagged.' : isActive ? 'Your clock is running. Tap to switch turns.' : 'Tap to start or switch to this turn.'}`);
      player.status.textContent = flaggedPlayer === name ? 'Flag!' : isActive ? 'Your turn' : activePlayer === name && !running ? 'Paused' : activePlayer ? 'Waiting' : 'Ready';
    }
    pauseButton.disabled = !activePlayer || !!flaggedPlayer;
    pauseButton.textContent = running ? 'Pause' : 'Resume';
    pauseButton.setAttribute('aria-pressed', String(!running && !!activePlayer));
  }

  function stopTimer() {
    if (timerId !== null) window.clearInterval(timerId);
    timerId = null;
  }

  function tick() {
    if (!running || !activePlayer) return;
    const now = performance.now();
    players[activePlayer].remaining -= now - lastTick;
    lastTick = now;
    if (players[activePlayer].remaining <= 0) {
      players[activePlayer].remaining = 0;
      flaggedPlayer = activePlayer;
      running = false;
      stopTimer();
      message.textContent = `${flaggedPlayer === 'white' ? 'White' : 'Black'} — Flag!`;
    }
    render();
  }

  function startTurn(name) {
    if (flaggedPlayer) return;
    tick();
    if (flaggedPlayer) return;
    activePlayer = name;
    running = true;
    lastTick = performance.now();
    message.textContent = `${name === 'white' ? 'White' : 'Black'} to move.`;
    stopTimer();
    timerId = window.setInterval(tick, 100);
    render();
  }

  for (const [name, player] of Object.entries(players)) {
    player.button.addEventListener('click', () => startTurn(name));
  }

  pauseButton.addEventListener('click', () => {
    if (!activePlayer || flaggedPlayer) return;
    if (running) {
      tick();
      if (flaggedPlayer) return;
      running = false;
      stopTimer();
      message.textContent = 'Clock paused.';
    } else {
      running = true;
      lastTick = performance.now();
      message.textContent = `${activePlayer === 'white' ? 'White' : 'Black'} to move.`;
      timerId = window.setInterval(tick, 100);
    }
    render();
  });

  render();
})();
